use core::ffi::c_void;
use mechanical_mimalloc::raw::{
    mi_bench_page_batch_fixture_destroy, mi_bench_page_batch_fixture_new,
    mi_bench_page_batch_fixture_prepare, mi_bench_page_batch_fixture_run,
};
use std::time::{Duration, Instant};

#[inline(never)]
#[unsafe(link_section = ".borrowed_collection_caller")]
fn measure(fixtures: &[*mut c_void], rounds: usize) -> u128 {
    let mut elapsed = Duration::ZERO;
    for _ in 0..rounds {
        for &fixture in fixtures {
            assert!(unsafe { mi_bench_page_batch_fixture_prepare(fixture) });
        }
        let start = Instant::now();
        let mut completed = true;
        for &fixture in fixtures {
            completed &= unsafe { mi_bench_page_batch_fixture_run(fixture) };
        }
        elapsed += start.elapsed();
        assert!(completed);
    }
    elapsed.as_nanos()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let kind: u8 = args[1].parse().unwrap();
    let len: usize = args[2].parse().unwrap();
    let destination: usize = args[3].parse().unwrap();
    let rounds: usize = args[4].parse().unwrap();
    let live: usize = args[5].parse().unwrap();
    let fixtures: Vec<_> = (0..live)
        .map(|_| {
            let fixture = mi_bench_page_batch_fixture_new(kind, len, destination);
            assert!(!fixture.is_null());
            fixture
        })
        .collect();
    std::hint::black_box(measure(&fixtures, 128));
    let elapsed = measure(&fixtures, rounds);
    for fixture in fixtures {
        unsafe { mi_bench_page_batch_fixture_destroy(fixture) };
    }
    println!("{elapsed}");
}

